package ro.leo.visual;
import org.json.*;import org.xmlpull.v1.*;import android.util.Xml;import java.io.*;import java.net.*;import java.util.*;
/** RSS/Atom text and audio enclosures. Bounded, explicit fetch, no script execution. */
final class PocketFeeds {
 static byte[] fetch(String raw)throws Exception{String current=PocketStore.url(raw);for(int redirect=0;redirect<5;redirect++){HttpURLConnection c=(HttpURLConnection)new URL(current).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","LeoPocket/1.0");try{int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");if(location==null)throw new IOException("Missing redirect");String next=PocketStore.url(new URL(new URL(current),location).toString());if(current.startsWith("https:")&&!next.startsWith("https:"))throw new IOException("HTTPS downgrade refused");current=next;continue;}if(code!=200)throw new IOException("HTTP "+code);try(InputStream in=c.getInputStream()){return PocketStore.bytes(in,2*1024*1024);}}finally{c.disconnect();}}throw new IOException("Too many redirects");}
 static String plain(String s){return UiText.preview(android.text.Html.fromHtml(s==null?"":s,android.text.Html.FROM_HTML_MODE_LEGACY).toString(),12000);}
 static JSONArray parse(byte[] bytes,String base)throws Exception{if(bytes.length>2*1024*1024)throw new IOException("Feed too large");XmlPullParser p=Xml.newPullParser();p.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES,true);p.setInput(new ByteArrayInputStream(bytes),null);JSONArray out=new JSONArray();JSONObject item=null;int itemDepth=-1;String field=null;int fieldDepth=-1;StringBuilder content=new StringBuilder();int events=0;
 for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.nextToken()){if(++events>100000)throw new IOException("XML limit");if(event==XmlPullParser.DOCDECL)throw new IOException("DTD not allowed");String name=p.getName();if(event==XmlPullParser.START_TAG){if(("item".equals(name)||"entry".equals(name))&&item==null){item=new JSONObject();itemDepth=p.getDepth();}else if(item!=null){if("enclosure".equals(name)){String url=p.getAttributeValue(null,"url");if(url!=null)item.put("audio",resolve(base,url));}else if("link".equals(name)&&p.getAttributeValue(null,"href")!=null){String href=p.getAttributeValue(null,"href"),rel=p.getAttributeValue(null,"rel");if("enclosure".equals(rel))item.put("audio",resolve(base,href));else if(rel==null||"alternate".equals(rel))item.put("link",resolve(base,href));}if(field==null&&Arrays.asList("title","description","summary","content","encoded","link","pubDate","updated","guid","id").contains(name)){field=name;fieldDepth=p.getDepth();content.setLength(0);}}}else if((event==XmlPullParser.TEXT||event==XmlPullParser.CDSECT||event==XmlPullParser.ENTITY_REF)&&field!=null){String text=p.getText();if(text!=null){if(content.length()+text.length()>32768)throw new IOException("Item text too large");content.append(text);}}else if(event==XmlPullParser.END_TAG&&item!=null){if(field!=null&&p.getDepth()==fieldDepth){String value=content.toString();if("title".equals(field))item.put("title",plain(value));else if("link".equals(field)&&!value.trim().isEmpty())item.put("link",resolve(base,value.trim()));else if(Arrays.asList("description","summary","content","encoded").contains(field)){if(value.length()>item.optString("body").length())item.put("body",plain(value));}else item.put(field,value);field=null;}if(p.getDepth()==itemDepth){if(!item.optString("title").isEmpty()){item.put("key",item.optString("guid",item.optString("id",item.optString("link",item.optString("title")))));out.put(item);if(out.length()>=100)break;}item=null;}}}return out;}
 static String resolve(String base,String address){try{return PocketStore.url(new URL(new URL(base),address).toString());}catch(Exception e){return "";}}
}
